const PREVIEW=/[?&]preview\b/.test(location.search);if(PREVIEW&&window.CFL_CONFIG){window.CFL_CONFIG.firebase=null;window.CFL_CONFIG.requireCode=false;}const CFG=window.CFL_CONFIG||{},modules=curriculum(CFG),loaded=load();const PREVIEW_MODULE=PREVIEW?new URLSearchParams(location.search).get('module'):null;if(PREVIEW_MODULE&&CFG.curriculum){CFG.curriculum.openMap=true;}if(PREVIEW){const b=document.createElement('div');b.className='preview-banner';b.textContent='Preview mode: nothing here is saved to the class record. Close the tab to discard.';document.body.prepend(b);}let S=loaded.state,storageError=loaded.error;function ensurePrep(){S.testPrep=S.testPrep||{history:{operating:[],investing:[],financing:[]},active:null};S.testPrep.history=S.testPrep.history||{};for(const k of ['operating','investing','financing'])S.testPrep.history[k]=S.testPrep.history[k]||[];}ensurePrep();
const app=document.querySelector('#app'),drawer=document.querySelector('#drawer');
const cloud=createCloud(CFG,()=>S,()=>persist(false),status=>{const el=document.querySelector('#save-status');if(!storageError)el.textContent=status;});
function persist(sync=true){if(storageError?.startsWith('Saved progress'))return;if(!save(S)){storageError='Progress could not be saved on this device. Export a backup in Settings before closing.';document.querySelector('#save-status').textContent=storageError;document.querySelector('#save-status').classList.add('error');}if(sync)cloud.schedule();}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',4500);}
function modal(title,html){document.querySelector('#drawer-title').textContent=title;document.querySelector('#drawer-body').innerHTML=html;if(!drawer.open)drawer.showModal();}
function close(){drawer.close();}
function route(name){S.route=name;persist();render();window.scrollTo({top:0,behavior:'instant'});}
function currentModule(){return modules.find(m=>m.id===S.active?.moduleId)||modules[S.lesson.currentModule]||modules[0];}
function introduce(c){if(c&&!S.lesson.introducedConcepts.includes(c))S.lesson.introducedConcepts.push(c);}
function newActive(problem,extras={}){return {problem,step:0,drafts:{},help:{},feedback:null,done:false,lines:[],sourceTab:problem.prompts?.[0]?.sourceTab||problem.sourceTab||(problem.source?.bs?.length?'bs':problem.source?.is?.length?'is':'supplemental'),opportunityId:id(),startedAt:Date.now(),...extras};}
function suspendLesson(){if(S.active?.mode==='learn')(S.lesson.suspended||={})[S.active.moduleId]=S.active;}
function startModule(moduleId,resume=true){const m=modules.find(x=>x.id===moduleId);if(!m)return;suspendLesson();S.lesson.currentModule=modules.indexOf(m);if(resume&&S.lesson.suspended?.[moduleId]){S.active=S.lesson.suspended[moduleId];route('lesson');return;}const items=lesson(moduleId,CFG);const pos=resume?(S.lesson.positions[moduleId]||0):0;S.lesson.positions[moduleId]=Math.min(pos,items.length-1);setLessonItem(moduleId,S.lesson.positions[moduleId]);}
function setLessonItem(moduleId,index){const items=lesson(moduleId,CFG),item=items[index];if(!item){completeModule(moduleId);return;}introduce(item.concept||moduleId);S.active=newActive(item,{moduleId,itemIndex:index,mode:'learn'});S.route='lesson';persist();render();}
function completeModule(moduleId){delete S.lesson.suspended?.[moduleId];if(!S.lesson.completedModules.includes(moduleId))S.lesson.completedModules.push(moduleId);if(REVISIT_REQUIRED[moduleId]){S.lesson.revisited=S.lesson.revisited||{};S.lesson.revisited[moduleId]=REVISIT_REQUIRED[moduleId];S.lesson.updated=(S.lesson.updated||[]).filter(x=>x!==moduleId);}const missed=S.attempts.filter(a=>a.moduleId===moduleId&&!a.correct);if(missed.length&&!S.lesson.revisit.includes(moduleId))S.lesson.revisit.push(moduleId);S.lesson.positions[moduleId]=0;S.active=null;S.route='module-done';S.completedNow=moduleId;persist();render();}
function nextProblem(){const a=S.active;if(!a)return;if(a.problem.type!=='observe')S.opportunities++;if(a.mode==='practice'){S.practice.done++;if(S.practice.done>=S.practice.size){if(S.practice.focus)S.afterFocus=S.practice.focus;else S.afterFocus=null;S.active=null;S.route='practice-done';persist();render();return;}const p=selectPractice(S,CFG);S.active=newActive(p,{mode:'practice'});persist();render();return;}
 if(a.legacyLessonRevision){delete S.lesson.suspended?.[a.moduleId];setLessonItem(a.moduleId,0);return;}
 if(a.retrieval){const returnTo=a.returnTo;setLessonItem(returnTo.moduleId,returnTo.index);return;}
 const next=a.itemIndex+1;S.lesson.positions[a.moduleId]=next;
 // Sparse retrieval after a coherent item; never interleave facts inside a problem.
 if(next===2&&['borrowing'].includes(a.moduleId)&&S.lesson.introducedConcepts.includes('accounts_receivable')){const p=generate('accounts_receivable',S.opportunities*97+5,2,'decrease',CFG);p.prompts=p.prompts.filter(q=>q.skill==='recognition_cash_connect');p.intro='Quick retrieval · a new, separate A/R example';S.active=newActive(p,{mode:'learn',moduleId:a.moduleId,retrieval:true,returnTo:{moduleId:a.moduleId,index:next}});persist();render();return;}
 setLessonItem(a.moduleId,next);
}
function startPractice(focus=null,weak=false){suspendLesson();S.practice={focus,weak,done:0,size:focus?(CFG.practice?.focusSize||6):(CFG.practice?.mixedSize||10),seed:Date.now()%1000000,afterFocus:S.afterFocus};const p=selectPractice(S,CFG);if(!p){toast('Start a learning module to introduce a concept first.');return;}S.active=newActive(p,{mode:'practice'});S.route='lesson';persist();render();}
function moduleHead(m,itemIndex,total){const c=TIMING[m.id];return `<div class="module-head"><div><div class="eyebrow">${esc(m.group)} · ${Math.min(itemIndex+1,total)} of ${total} learning steps</div><h1>${esc(conceptName(m.id,CFG)===m.id?m.title:m.title==='Unearned Revenue'?conceptName(m.id,CFG):m.title)}</h1><div class="purpose"><p><b>What:</b> ${esc(m.what||`Explain ${conceptName(m.id,CFG)} changes using recognition and cash.`)}</p><p><b>Why:</b> ${esc(m.why||c?.why)}</p><p><b>You’ll know:</b> ${esc(m.know||'You can find the account, explain the change, and derive its Operating adjustment.')}</p></div></div><div class="head-side"><span class="status">${S.active?.mode==='practice'?'Practice':'Learn at your pace'}</span><div class="head-nav">${S.active?.mode==='learn'&&!S.active?.retrieval&&!S.active?.legacyLessonRevision&&(itemIndex>0||S.active?.step>0)?'<button class="link" id="lesson-back">← Back a step</button>':''}${S.testPrep?.returnTo?'<button class="link" data-go="testprep">↩ Back to Test Prep</button>':''}<button class="link" data-go="home">← Learning path</button></div></div></div>`;}
function lessonBack(){const a=S.active;if(!a||a.mode!=='learn')return;if(a.problem.type!=='observe'&&a.step>0){a.step--;a.done=false;a.feedback=null;persist();renderLesson();return;}const idx=a.itemIndex-1;if(idx<0)return;const items=lesson(a.moduleId,CFG);S.lesson.positions[a.moduleId]=idx;const item=items[idx];S.active=newActive(item,{moduleId:a.moduleId,itemIndex:idx,mode:'learn'});if(item.type!=='observe'){S.active.step=item.prompts.length-1;}persist();render();}
function render(){document.title=CFG.appName||'Cash Flow Lab';document.querySelectorAll('[data-app-name]').forEach(e=>e.textContent=CFG.appName||'Cash Flow Lab');document.documentElement.dataset.theme=S.settings.theme||'light';document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',S.route===b.dataset.nav||(b.dataset.nav==='home'&&['lesson','module-done'].includes(S.route))));
 if(!S.identity){renderJoin();return;}
 if(S.route==='lesson'&&S.active){renderLesson();return;}
 if(S.route==='capstone'){app.innerHTML=renderBuilder(S,CFG);wireBuilder();return;}
 if(S.route==='module-done'){renderModuleDone();return;}
 if(S.route==='practice-done'){app.innerHTML=`<section class="result card"><div class="check">✓</div><div class="eyebrow">Practice complete</div><h1>Good work connecting the dots.</h1><p>Your recent evidence and next practice priorities are saved.</p><p class="small muted">Next: ${esc(nextAction().why)}</p><div class="row"><button class="primary" id="journey-go">${esc(nextAction().label)} →</button><button data-start-mixed>Another mixed set</button>${S.testPrep?.returnTo?'<button data-go="testprep">↩ Back to Test Prep</button>':''}<button data-go="home">Learning map</button></div></section>`;wireCommon();return;}
 if(S.route==='testprep'){renderTestPrep();return;}
 if(S.route==='practice'){renderPractice();return;}
 if(S.route==='build'){renderBuild();return;}
 if(S.route==='progress'){renderProgress();return;}
 renderHome();
}
function renderJoin(){app.innerHTML=`<section class="join"><div><div class="eyebrow">Advanced accounting · an interactive lab</div><h1>There’s a story<br>behind every<br><em>cash movement.</em></h1><p class="muted">Learn to find it, explain it, and build a complete Statement of Cash Flows.</p><div class="notice">One company. One step at a time.<br>No timer. Pick up where you leave off.</div></div><form id="join" class="card"><h2>Make yourself at home.</h2><p class="small">Use only your first name and last initial.</p><label class="field">First name<input name="first" autocomplete="off" required maxlength="30" placeholder="Alex"></label><label class="field">Last initial<input name="initial" autocomplete="off" required maxlength="1" pattern="[A-Za-z]" placeholder="R"></label><label class="field">Class<select name="block">${(CFG.blocks||[{id:'1',name:'Advanced Accounting'}]).map(b=>`<option value="${esc(b.id)}">${esc(b.name)}</option>`).join('')}</select></label>${CFG.requireCode?'<label class="field">Class code<input name="code" required autocomplete="off"></label>':''}<p id="join-error" class="form-error" role="alert">${esc(storageError||'')}</p><button class="primary" type="submit">Start learning →</button><p class="small" style="margin-top:16px">${CFG.firebase?'Progress saves here and to the class record.':'Progress saves in this browser. Use Settings to export a backup.'}</p></form></section>`;document.querySelector('#join').onsubmit=e=>{e.preventDefault();const d=new FormData(e.currentTarget),block=(CFG.blocks||[]).find(b=>b.id===d.get('block'));if(CFG.requireCode&&String(d.get('code')).trim()!==block?.code){document.querySelector('#join-error').textContent='That class code does not match. Ask Mr. Sorensen.';return;}const first=String(d.get('first')).trim().split(/\s+/)[0],initial=String(d.get('initial')).trim().slice(0,1).toUpperCase();if(!first||!initial)return;S.identity={name:`${first} ${initial}.`,block:String(d.get('block'))};persist();render();};}
function capstoneGates(){const sum=summarize(S,CFG);const secureOps=['accounts_receivable','accounts_payable','accrued_liabilities','unearned_revenue','prepaid_expenses','inventory','depreciation','gain_on_sale','loss_on_sale'].filter(c=>['Secure','Mastered'].includes(sum.concepts?.[c]?.state)).length;const acc=sum.recentAccuracy;const gateOn=CFG.capstones?.requireEvidence!==false;const guidedOK=!gateOn||(acc==null||acc>=0.6)&&secureOps>=3||!!S.capstones['beacon-guided']?.completed;const integratedOK=!gateOn||!!S.capstones['beacon-guided']?.completed&&(acc==null||acc>=0.7)&&secureOps>=5||!!S.capstones['beacon-integrated']?.completed;return {secureOps,acc,gateOn,guidedOK,integratedOK,ready:!!S.capstones['beacon-integrated']?.completed};}
function nextAction(){const done=S.lesson.completedModules.length,total=modules.length;if(S.active?.mode==='learn'){const m=modules.find(x=>x.id===S.active.moduleId);return {stage:1,label:'Resume '+(m?.title||'your lesson'),why:`Learn · module ${modules.indexOf(m)+1} of ${total}`,run:()=>route('lesson')};}
 if(done<total){const m=resumeTarget();return {stage:1,label:(startedIdx(m.id)>=0?'Pick up ':'Start ')+m.title,why:`Learn · module ${modules.indexOf(m)+1} of ${total} · ${total-done} to go`,run:()=>startModule(m.id)};}
 const g=capstoneGates();if(!g.guidedOK)return {stage:2,label:'Practice my weakest skill',why:`Practice · recommended before the guided statement: 3 concepts Secure and 60% accuracy (now ${g.secureOps} and ${g.acc==null?'—':Math.round(g.acc*100)+'%'}); you can open it anytime`,run:()=>startPractice(null,true)};
 if(!S.capstones['beacon-guided']?.completed)return {stage:3,label:(S.capstones['beacon-guided']?'Resume':'Open')+' the guided statement',why:'Build · statement 1 of 3',run:()=>{startCapstone(S,'beacon-guided');persist();render();}};
 if(!g.integratedOK)return {stage:2,label:'Practice my weakest skill',why:`Practice · recommended before the integrated statement: 5 concepts Secure and 70% accuracy (now ${g.secureOps} and ${g.acc==null?'—':Math.round(g.acc*100)+'%'}); you can open it anytime`,run:()=>startPractice(null,true)};
 if(!S.capstones['beacon-integrated']?.completed)return {stage:3,label:(S.capstones['beacon-integrated']?'Resume':'Open')+' the integrated statement',why:'Build · statement 2 of 3',run:()=>{startCapstone(S,'beacon-integrated');persist();render();}};
 if(!S.capstones['cedar-independent']?.completed)return {stage:3,label:(S.capstones['cedar-independent']?'Resume':'Open')+' the independent statement',why:'Build · statement 3 of 3',run:()=>{startCapstone(S,'cedar-independent');persist();render();}};
 return {stage:3,label:'Keep practicing (mixed set)',why:'All three statements built. Practice keeps the skills sharp.',run:()=>startPractice()};}
function journeyHTML(){const a=nextAction();const done=S.lesson.completedModules.length,total=modules.length;const built=['beacon-guided','beacon-integrated','cedar-independent'].filter(id=>S.capstones[id]?.completed).length;const steps=[['1','Learn',`${done}/${total} modules`],['2','Practice',done<total?'after the modules':'until concepts are Secure'],['3','Build',`${built}/3 statements`]];return `<section class="journey" aria-label="Your sequence"><div class="journey-steps">${steps.map((s,i)=>`<div class="jstep ${a.stage===i+1?'now':a.stage>i+1?'done':''}"><span class="jnum">${s[0]}</span><span><b>${s[1]}</b><small>${s[2]}</small></span></div>${i<2?'<span class="jarrow" aria-hidden="true">→</span>':''}`).join('')}</div><div class="journey-next"><button class="primary" id="journey-go">${esc(a.label)} →</button><small>${esc(a.why)}</small></div></section>`;}
function wireJourney(){const b=document.querySelector('#journey-go');if(b)b.onclick=()=>nextAction().run();}
function startedIdx(id){return (S.lesson.positions?.[id]>0||!!S.lesson.suspended?.[id])?modules.findIndex(m=>m.id===id):-1;}
function resumeTarget(exclude=null){const done=S.lesson.completedModules;const inc=m=>!done.includes(m.id)&&m.id!==exclude;const started=modules.filter(m=>inc(m)&&startedIdx(m.id)>=0);if(started.length)return started.at(-1);const lastDone=Math.max(-1,...done.map(id=>modules.findIndex(m=>m.id===id)));const after=modules.slice(lastDone+1).find(inc);if(after)return after;return modules.find(inc)||modules.at(-1);}
function openUpTo(){const lastDone=Math.max(-1,...S.lesson.completedModules.map(id=>modules.findIndex(m=>m.id===id)));const started=Math.max(-1,...modules.map(m=>startedIdx(m.id)));return Math.max(lastDone+1,started);}

// ---------- Test Prep ----------
const SECTION_TITLE={operating:'Operating section',investing:'Investing section',financing:'Financing section'};
const SECTION_BLURB={operating:'Start from net income, add back noncash expenses, undo gains and losses, then adjust for each current asset and current liability change.',investing:'Actual cash paid or received for long-term assets. Only the cash part counts; no net income here.',financing:'Actual cash from or back to lenders and owners: principal and capital, never interest.'};

// ---------- Operating warm-up: one fixed sequence before the paper test ----------
const WARM_STEPS=['See one built','Build one (Level 1)','Build one (Level 2)','Why does each line go that way?','Say it in words'];
const WARM_MC=[
 {q:'The operating section (indirect method) starts from which number?',opts:['Sales revenue','Net income','The change in cash','Total current assets'],ans:1,why:'The indirect method starts from net income and then fixes it, line by line, until it becomes cash from operations.'},
 {q:'Depreciation expense is added back to net income. Why?',opts:['Depreciation brought cash in this year','Depreciation lowered net income, but no cash was paid for it this year','Depreciation is a financing activity','It is not added back; it is subtracted'],ans:1,why:'The cash for the asset left when it was bought. This year’s depreciation is an expense with no cash behind it, so it is added back.'},
 {q:'A company sold equipment and recorded a $2,000 gain. In the operating section, the gain is',opts:['added, because the company got cash','subtracted, because the gain is in net income but the sale cash is reported in investing','ignored','added twice'],ans:1,why:'The gain pushed net income up, but the sale is not day-to-day business. All the sale cash goes in investing, so the gain is removed from operating to avoid counting it twice.'},
 {q:'A company sold a truck and recorded a $1,500 loss. In the operating section, the loss is',opts:['added back','subtracted','placed in financing','ignored'],ans:0,why:'A loss pulled net income down, but no operating cash left because of it. Add it back; the sale cash is in investing.'},
 {q:'Accounts Receivable went from $18,000 to $22,000. What does that tell you?',opts:['Customers paid more than this year’s sales; add $4,000','Customers still owe $4,000 more than before, so cash lagged behind sales; subtract $4,000','Nothing; receivables are not operating','Subtract $22,000'],ans:1,why:'A bigger receivable balance means more sales are uncollected. Net income counted them; cash did not arrive. Subtract the increase.'},
 {q:'Accounts Payable went from $19,000 down to $16,000. In the operating section you',opts:['add $3,000, because the company owes less','subtract $3,000, because the company paid down old bills with cash','add $16,000','do nothing'],ans:1,why:'Owing less means cash went out to pay bills recorded in an earlier year. That cash is not in this year’s expenses, so subtract the decrease.'},
 {q:'Which of these is NOT an operating activity?',opts:['Collecting cash from customers','Paying wages','Borrowing $10,000 from a bank','Paying a supplier'],ans:2,why:'Borrowing is cash from a lender: a financing activity. The other three are day-to-day business.'},
 {q:'Unearned Revenue went up $3,000 during the year. In the operating section you',opts:['subtract $3,000','add $3,000, because customers paid cash before the work was done','put $3,000 in investing','ignore it, because it is not a cash account'],ans:1,why:'Customers paid ahead. Cash came in but net income has not counted it yet, so add the increase.'},
 {q:'Prepaid rent went from $2,000 to $3,000. (Prepaid rent and prepaid insurance are prepaid expenses.) In the operating section you',opts:['add $1,000','subtract $1,000, because cash was paid ahead for rent that is not yet an expense','add $3,000','ignore it'],ans:1,why:'Paying ahead means cash left before the expense was recorded. A prepaid expense going up is a current asset going up: subtract.'},
 {q:'“Net cash provided by operating activities: $23,000” means',opts:['net income was $23,000','day-to-day business brought in $23,000 more cash than it paid out','the company’s cash balance rose by $23,000','sales were $23,000'],ans:1,why:'It is the cash result of operations only. Net income and the total change in cash are different numbers.'},
];
const WARM_SAY=[
 {q:'Why is an increase in Accounts Receivable subtracted from net income?',model:'Net income counts all sales, but when Accounts Receivable goes up, some of those sales have not been collected in cash yet. Subtracting the increase removes the sales that did not bring in cash this year.'},
 {q:'Why is a gain on the sale of equipment subtracted from net income, even though the company received cash?',model:'The gain raised net income, but it is not cash from day-to-day operations. All of the cash from the sale is reported in investing activities. Subtracting the gain keeps it from being counted in both sections.'},
];
function startWarmup(){S.testPrep.warmup={step:1,mc:{i:0,picked:null,correct:0,done:false},say:{i:0,typed:'',shown:false},started:Date.now()};S.testPrep.active=null;persist();warmupGo();}
function warmupGo(){const w=S.testPrep.warmup;if(!w)return;if(w.step===1){prepWorked('operating');S.testPrep.active.warmup=true;persist();render();return;}
 if(w.step===2){startPrep('operating',1);S.testPrep.active.warmup=true;persist();render();return;}
 if(w.step===3){startPrep('operating',2);S.testPrep.active.warmup=true;persist();render();return;}
 S.testPrep.active=null;S.route='testprep';persist();render();window.scrollTo({top:0,behavior:'instant'});}
function warmupNext(){const w=S.testPrep.warmup;if(!w)return;w.step++;persist();warmupGo();}
function warmupBar(){const w=S.testPrep.warmup;if(!w)return '';const mins=Math.round((Date.now()-w.started)/60000);return `<div class="warm-bar"><b>Operating warm-up</b> · step ${Math.min(w.step,5)} of 5: ${esc(WARM_STEPS[Math.min(w.step,5)-1]||'')} <span class="muted small">· ${mins} min so far</span><div class="warm-steps">${WARM_STEPS.map((s,i)=>`<span class="${i+1<w.step?'done':i+1===w.step?'now':''}">${i+1}</span>`).join('')}</div></div>`;}
function renderWarmupMC(){const w=S.testPrep.warmup,mc=w.mc;const item=WARM_MC[mc.i];
 if(mc.done){app.innerHTML=`${warmupBar()}<div class="eyebrow">Warm-up · step 4 of 5</div><h1 style="font-size:2.2rem">${mc.correct} of ${WARM_MC.length} right</h1><p class="muted">${mc.correct>=8?'You can explain the rules, not just apply them. One more step.':'Reread the explanations that surprised you; the paper test asks these same ideas in its own words.'}</p><div class="row"><button class="primary" id="warm-next">Last step: say it in words →</button><button id="warm-redo">Go through the 10 again</button></div>`;document.querySelector('#warm-next').onclick=warmupNext;document.querySelector('#warm-redo').onclick=()=>{w.mc={i:0,picked:null,correct:0,done:false};persist();render();};wireCommon();return;}
 const picked=mc.picked;app.innerHTML=`${warmupBar()}<div class="eyebrow">Warm-up · step 4 of 5 · question ${mc.i+1} of ${WARM_MC.length}</div><h1 style="font-size:1.8rem">${esc(item.q)}</h1><div class="stack warm-opts">${item.opts.map((o,k)=>`<button class="opt ${picked==null?'':k===item.ans?'right':k===picked?'wrong':'dim'}" data-opt="${k}" ${picked!=null?'disabled':''}>${'ABCD'[k]}.  ${esc(o)}</button>`).join('')}</div>${picked==null?'':`<div class="notice ${picked===item.ans?'ok':'bad'}"><b>${picked===item.ans?'Right.':'Not quite. The answer is '+'ABCD'[item.ans]+'.'}</b> ${esc(item.why)}</div><div class="row"><button class="primary" id="warm-mc-next">${mc.i+1<WARM_MC.length?'Next question →':'See my score →'}</button></div>`}`;
 document.querySelectorAll('[data-opt]').forEach(b=>b.onclick=()=>{mc.picked=Number(b.dataset.opt);if(mc.picked===item.ans)mc.correct++;persist();render();});
 document.querySelector('#warm-mc-next')?.addEventListener('click',()=>{mc.i++;mc.picked=null;if(mc.i>=WARM_MC.length){mc.done=true;(S.testPrep.history.warmup||(S.testPrep.history.warmup=[])).push({level:0,score:mc.correct,max:WARM_MC.length,ts:Date.now(),wrong:[]});cloud.schedule?.();}persist();render();});wireCommon();}
function renderWarmupSay(){const w=S.testPrep.warmup,s=w.say;const item=WARM_SAY[s.i];
 if(s.i>=WARM_SAY.length){app.innerHTML=`${warmupBar()}<div class="eyebrow">Warm-up complete</div><h1 style="font-size:2.2rem">You are ready for the paper test.</h1><p class="muted">You built the section twice, answered the “why” questions, and put the two big reasons into your own words. The paper test asks the same things with different numbers.</p><ul class="small"><li>Net income first.</li><li>Add back depreciation; subtract a gain; add back a loss.</li><li>Current asset up → subtract; down → add.</li><li>Current liability up → add; down → subtract.</li><li>Long-term accounts and Cash itself are not in Operating.</li></ul><div class="row"><button class="primary" id="warm-finish">Close the warm-up</button><button id="warm-more">One more Level 2 round</button></div>`;document.querySelector('#warm-finish').onclick=()=>{S.testPrep.warmup.finished=Date.now();persist();render();};document.querySelector('#warm-more').onclick=()=>startPrep('operating',2);wireCommon();return;}
 app.innerHTML=`${warmupBar()}<div class="eyebrow">Warm-up · step 5 of 5 · ${s.i+1} of ${WARM_SAY.length}</div><h1 style="font-size:1.8rem">${esc(item.q)}</h1><p class="muted">Write one or two sentences in your own words. Then compare with the model answer. The paper test has two questions like this.</p><textarea id="warm-say" rows="4" style="width:100%;max-width:700px;font:inherit;padding:8px" ${s.shown?'disabled':''}>${esc(s.typed||'')}</textarea><div class="row" style="margin-top:8px">${s.shown?`<button class="primary" id="warm-say-next">${s.i+1<WARM_SAY.length?'Next →':'Finish →'}</button>`:`<button class="primary" id="warm-say-show">Compare with the model answer</button>`}</div>${s.shown?`<div class="notice ok"><b>Model answer.</b> ${esc(item.model)}<br><span class="small muted">Full credit needs both ideas: what net income counted, and why the cash is different.</span></div>`:''}`;
 const ta=document.querySelector('#warm-say');ta?.addEventListener('input',e=>{s.typed=e.target.value;persist();});
 document.querySelector('#warm-say-show')?.addEventListener('click',()=>{if((s.typed||'').trim().length<15){toast('Write at least a sentence first.');return;}s.shown=true;persist();render();});
 document.querySelector('#warm-say-next')?.addEventListener('click',()=>{s.i++;s.typed='';s.shown=false;persist();render();});wireCommon();}
function prepWeakHTML(){const counts={},links={};for(const sec of ['operating','investing','financing'])for(const h of (S.testPrep.history[sec]||[]).slice(-6)){for(const w of (h.wrong||[])){const k=sec+'|'+w;counts[k]=(counts[k]||0)+1;if(h.links?.[w])links[k]=h.links[w];}}const top=Object.entries(counts).filter(([k,n])=>n>=2).sort((a,b)=>b[1]-a[1]).slice(0,5);if(!top.length)return '';return `<section class="card prep-weak"><h2>Focus on these first</h2><p class="small muted">Lines you have missed more than once in your recent rounds.</p><ul>${top.map(([k,n])=>{const [sec,w]=k.split('|');const [mod,con]=links[k]||['',''];return `<li><b>${esc(w)}</b> <span class="muted small">(${sec}, missed ${n}×)</span> ${mod?`<button type="button" class="link small" data-prep-learn="${esc(mod)}">theory</button>`:''}${con?` · <button type="button" class="link small" data-prep-practice="${esc(con)}">practice</button>`:''}</li>`;}).join('')}</ul></section>`;}
function prepBest(sec){const h=S.testPrep.history[sec]||[];if(!h.length)return null;const best=h.reduce((b,x)=>x.score/x.max>b.score/b.max?x:b,h[0]);return {best,last:h.at(-1),n:h.length};}
function prepLearn(moduleId){S.testPrep.returnTo=true;persist();startModule(moduleId);}
function prepPractice(concept){S.testPrep.returnTo=true;introduce(concept);persist();startPractice(concept);}
function prepWorked(sec){S.testPrep.active={section:sec,level:1,seed:(sec==='operating'?3:sec==='investing'?5:3),draft:{},graded:true,showWhere:true,showAnswer:true,worked:true};const sc=prepScenario(sec,S.testPrep.active.seed,1);if(sc.start)S.testPrep.active.draft.__start=sc.start.amount;S.testPrep.active.draft.__total=sc.total;for(const it of sc.items)S.testPrep.active.draft[it.id]={effect:it.correct.effect,amount:it.correct.effect==='none'?'':it.correct.amount};S.route='testprep';persist();render();window.scrollTo({top:0,behavior:'instant'});}
function startPrep(sec,level){S.testPrep.active={section:sec,level,seed:(Date.now()%100000)+1,draft:{},graded:null,showWhere:level===1,showAnswer:false};S.route='testprep';persist();render();window.scrollTo({top:0,behavior:'instant'});}
function renderTestPrep(){S.testPrep.returnTo=false;const a=S.testPrep.active;const banner=CFG.testPrep?.banner||'Before the paper test: do the Operating warm-up (about 20 minutes).';
 const w=S.testPrep.warmup;if(!a&&w&&!w.finished&&w.step===4){renderWarmupMC();return;}if(!a&&w&&!w.finished&&w.step===5){renderWarmupSay();return;}
 if(!a){app.innerHTML=`<div class="eyebrow">Test Prep · build each section the way the test asks</div><h1 style="font-size:2.6rem">Practice the test, not just the ideas.</h1>${(()=>{const w=S.testPrep.warmup;const done=w?.finished;return `<section class="card warm-card"><h2>Operating warm-up <span class="pill">do this today</span></h2><p>One fixed sequence, about 20 minutes: see one section built → build one yourself (Level 1) → build one with a gain (Level 2) → ten “why” questions with the reason after each → put two reasons into your own words. ${done?'<b>Done.</b> You can run it again or do more rounds.':w?`<b>In progress:</b> step ${Math.min(w.step,5)} of 5.`:''}</p><div class="row"><button class="primary" id="warm-start">${done?'Run the warm-up again':w?'Continue the warm-up →':'Start the warm-up →'}</button>${w&&!done?'<button id="warm-restart">Restart from step 1</button>':''}</div></section>`;})()}<p class="muted">Each round shows the documents a test shows (income statement, comparative balance sheet, extra facts) and a blank section. You decide, line by line, what goes in, which way, and how much, then enter the total. You get a per-line check with the reason, and the worked answer in statement form. New numbers every time.</p>${prepWeakHTML()}<div class="practice-grid">${['operating','investing','financing'].map(sec=>{const b=prepBest(sec);return `<section class="card ${sec==='operating'?'prep-focus':''}"><h2>${SECTION_TITLE[sec]}${sec==='operating'?' <span class="pill">on tomorrow’s quiz</span>':''}</h2><p class="muted">${SECTION_BLURB[sec]}</p>${b?`<p class="small">Best: <b>${b.best.score}/${b.best.max}</b> (level ${b.best.level}) · last: ${b.last.score}/${b.last.max} · ${b.n} round${b.n>1?'s':''}</p>`:'<p class="small muted">No rounds yet.</p>'}<details class="prep-how"><summary><b>How to build it</b> · the steps, in order</summary><ol class="small">${PREP_PROCEDURE[sec].map(s=>`<li>${esc(s)}</li>`).join('')}</ol><button class="small" data-prep-worked="${sec}">See one built, with reasons on every line →</button></details><div class="row" style="flex-wrap:wrap;gap:8px">${PREP_LEVELS.map(([n,name,hint])=>`<button class="${n==='2'?'primary':''}" data-prep="${sec}:${n}" title="${esc(hint)}">Level ${n} · ${name}</button>`).join('')}</div><p class="small muted">${sec==='operating'?PREP_LEVELS.map(([n,name,hint])=>`L${n}: ${hint}`).join(' · '):'L1: cash amounts stated · L2: amounts you must work out · L3: a no-cash deal and more distractors'}</p></section>`;}).join('')}</div>`;document.querySelectorAll('[data-prep]').forEach(b=>b.onclick=()=>{const [sec,l]=b.dataset.prep.split(':');startPrep(sec,Number(l));});document.querySelector('#warm-start')?.addEventListener('click',()=>{const w=S.testPrep.warmup;if(w&&!w.finished)warmupGo();else startWarmup();});document.querySelector('#warm-restart')?.addEventListener('click',startWarmup);document.querySelectorAll('[data-prep-worked]').forEach(b=>b.onclick=()=>prepWorked(b.dataset.prepWorked));document.querySelectorAll('[data-prep-learn]').forEach(b=>b.onclick=()=>prepLearn(b.dataset.prepLearn));document.querySelectorAll('[data-prep-practice]').forEach(b=>b.onclick=()=>prepPractice(b.dataset.prepPractice));wireCommon();return;}
 const sc=prepScenario(a.section,a.seed,a.level);const g=a.graded?prepGrade(sc,a.draft):null;const effects=effectsFor(a.section);
 const docs=`${sc.source.is.length?`<div class="statement">${sourceHTML(sc.source,'is',null,CFG)}</div>`:''}${sc.source.bs.length?`<div class="statement">${sourceHTML(sc.source,'bs',null,CFG)}</div>`:''}<div class="statement"><div class="statement-head"><strong>${esc(sc.company)}</strong><span>Additional information</span><span>${esc(sc.source.period)}</span></div><ol class="supp">${sc.source.supplemental.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></div>`;
 const links=it=>`<span class="prep-links small">${it.module?`<button type="button" class="link" data-prep-learn="${esc(it.module)}">theory</button>`:''}${it.concept?` · <button type="button" class="link" data-prep-practice="${esc(it.concept)}">practice</button>`:''}</span>`;const row=(it,i)=>{const d=a.draft[it.id]||{effect:'',amount:''};const r=g?g.rows.find(x=>x.item.id===it.id):null;return `<tr class="${r?(r.ok?'ok':'bad'):''}"><td><b>${esc(it.label)}</b> ${links(it)}${a.showWhere?`<br><small class="muted">${esc(it.source)}</small>`:''}${(r&&!r.ok)||a.worked?`<br><small class="${a.worked?'why ok-why':'why'}">${esc(it.why)}${r&&!r.ok&&r.effOK&&!r.amtOK?' (The direction was right; check the amount.)':''}</small>`:''}</td><td><select name="eff-${it.id}" ${g?'disabled':''}><option value="">—</option>${effects.map(([v,l])=>`<option value="${v}" ${d.effect===v?'selected':''}>${l}</option>`).join('')}</select></td><td><input name="amt-${it.id}" inputmode="numeric" placeholder="amount" value="${esc(String(d.amount||''))}" ${g?'disabled':''} ${d.effect==='none'?'style="opacity:.4"':''}></td><td class="mark">${r?(r.ok?'✓':'✗'):''}</td></tr>`;};
 app.innerHTML=`${a.warmup?warmupBar():''}<div class="eyebrow">Test Prep · ${SECTION_TITLE[sc.section]} · Level ${a.level}</div><h1 style="font-size:2.2rem">${esc(sc.company)}: ${a.worked?'one '+sc.section+' section, built for you':'build the '+sc.section+' section'}</h1>${a.worked?`<div class="notice"><b>Read this one, don’t fill it.</b> Every line is answered, with the reason under it in green. Click <b>theory</b> on any line for the lesson that teaches it, or <b>practice</b> for a short set on just that idea; a Back to Test Prep button brings you back here.</div>`:''}<p class="muted">${a.worked?'The steps are listed on the Test Prep page under “How to build it.”':'Use the company documents (income statement, balance sheet, additional information).'} For each item decide: not in this section, or in it with a direction and amount. Then enter the total. ${a.section==='operating'?'Start with net income.':''}</p><details class="prep-how" ${a.level===1||a.worked?'open':''}><summary><b>The steps</b> · keep these in view while you build</summary><ol class="small">${PREP_PROCEDURE[sc.section].map(s=>`<li>${esc(s)}</li>`).join('')}</ol></details><div class="prep-grid"><div class="prep-docs">${docs}</div><div class="prep-build card"><div class="statement-head"><strong>${esc(sc.company)}</strong><span>Statement of Cash Flows (partial)</span><span>Cash flows from ${sc.section} activities</span></div><form id="prep-form"><table class="prep-table"><thead><tr><th>Item</th><th>In this section?</th><th>Amount</th><th></th></tr></thead><tbody>${sc.start?`<tr class="${g?(g.startOK?'ok':'bad'):''}"><td><b>${esc(sc.start.label)}</b>${a.showWhere?'<br><small class="muted">Income statement, bottom line</small>':''}</td><td><small class="muted">always first</small></td><td><input name="start" inputmode="numeric" placeholder="amount" value="${esc(String(a.draft.__start||''))}" ${g?'disabled':''}></td><td class="mark">${g?(g.startOK?'✓':'✗'):''}</td></tr>`:''}${sc.items.map(row).join('')}<tr class="total ${g?(g.totalOK?'ok':'bad'):''}"><td colspan="2"><b>${esc(totalLabel(sc.section))}</b><br><small class="muted">use a minus sign or parentheses if cash went out</small></td><td><input name="total" placeholder="total" value="${esc(String(a.draft.__total||''))}" ${g?'disabled':''}></td><td class="mark">${g?(g.totalOK?'✓':'✗'):''}</td></tr></tbody></table><div class="row" style="flex-wrap:wrap;gap:8px;margin-top:10px">${g?'':'<button class="primary" type="submit">Check my section</button>'}<label class="small"><input type="checkbox" id="prep-where" ${a.showWhere?'checked':''}> show where each number comes from</label></div></form>${g?`<div class="prep-result"><h3>${a.worked?'Worked example, all lines shown':g.score+' of '+g.max+' right'}${a.worked?'':g.score===g.max?' · that is a full-credit section':g.score>=g.max*0.7?' · close; fix the ✗ lines':' · look at the reasons, then try the same numbers again'}</h3>${g.totalOK||a.worked?'':`<p class="small">Your total: ${esc(String(g.totalGiven))}. Correct total: ${esc(String(sc.total))}. ${sc.start&&g.startOK&&g.rows.every(r=>r.ok)?'Every line is right, so recheck the arithmetic.':'Fix the ✗ lines and the total will follow.'}</p>`}<div class="row" style="flex-wrap:wrap;gap:8px">${a.warmup?`<button class="primary" id="warm-next">Next step →</button>${a.worked?'':'<button id="prep-retry">Try again, same numbers</button>'}`:a.worked?`<button class="primary" id="prep-new">Now try one yourself (Level 1) →</button>`:`<button id="prep-retry">Try again, same numbers</button><button class="primary" id="prep-new">New numbers, same level</button>`}<button id="prep-answer">${a.showAnswer?'Hide':'Show'} the worked answer</button><button id="prep-exit">Back to Test Prep</button></div>${a.showAnswer?`<div class="statement" style="margin-top:12px">${answerStatementHTML(sc)}</div>`:''}</div>`:''}</div></div>`;
 const form=document.querySelector('#prep-form');
 form.addEventListener('input',e=>{const n=e.target.name||'';if(n.startsWith('eff-')){const idv=n.slice(4);a.draft[idv]={...(a.draft[idv]||{}),effect:e.target.value};if(e.target.value==='none'){a.draft[idv].amount='';form.querySelector(`[name="amt-${idv}"]`).value='';}form.querySelector(`[name="amt-${idv}"]`).style.opacity=e.target.value==='none'?.4:1;}else if(n.startsWith('amt-')){const idv=n.slice(4);a.draft[idv]={...(a.draft[idv]||{}),amount:e.target.value};}else if(n==='start')a.draft.__start=e.target.value;else if(n==='total')a.draft.__total=e.target.value;persist();});
 form.onsubmit=e=>{e.preventDefault();const missing=sc.items.filter(it=>!(a.draft[it.id]?.effect));if(missing.length){toast(`Decide every line first (${missing.length} left).`);return;}const res=prepGrade(sc,a.draft);a.graded=true;(S.testPrep.history[a.section]||=[]).push({level:a.level,score:res.score,max:res.max,ts:Date.now(),seed:a.seed,wrong:res.rows.filter(r=>!r.ok).map(r=>r.item.label).concat(res.totalOK?[]:['Total'],sc.start&&!res.startOK?['Net income']:[]),links:Object.fromEntries(res.rows.filter(r=>!r.ok&&(r.item.module||r.item.concept)).map(r=>[r.item.label,[r.item.module||'',r.item.concept||'']]))});persist();render();cloud.schedule?.();};
 document.querySelector('#prep-where').onchange=e=>{a.showWhere=e.target.checked;persist();render();};document.querySelectorAll('[data-prep-learn]').forEach(b=>b.onclick=()=>prepLearn(b.dataset.prepLearn));document.querySelectorAll('[data-prep-practice]').forEach(b=>b.onclick=()=>prepPractice(b.dataset.prepPractice));
 document.querySelector('#prep-retry')?.addEventListener('click',()=>{a.graded=null;a.showAnswer=false;persist();render();});document.querySelector('#warm-next')?.addEventListener('click',warmupNext);
 document.querySelector('#prep-new')?.addEventListener('click',()=>startPrep(a.section,a.level));
 document.querySelector('#prep-answer')?.addEventListener('click',()=>{a.showAnswer=!a.showAnswer;persist();render();});
 document.querySelector('#prep-exit')?.addEventListener('click',()=>{S.testPrep.active=null;persist();render();});
 wireCommon();}
function renderHome(){const next=S.active?.mode==='learn'&&modules.find(m=>m.id===S.active.moduleId)||resumeTarget(),resume=S.active!=null,limit=openUpTo();const pendingUpdated=(S.lesson.updated||[]).filter(id=>!S.lesson.completedModules.includes(id));const updatedNote=pendingUpdated.length?`<p class="notice">${pendingUpdated.length===1?'A lesson was':pendingUpdated.length+' lessons were'} rewritten after you did ${pendingUpdated.length===1?'it':'them'}: ${pendingUpdated.map(id=>esc(modules.find(m=>m.id===id)?.title||id)).join(', ')}. Keep going from where you left off; go through ${pendingUpdated.length===1?'it':'them'} again when you reach a good stopping point. Your earlier work and scores are kept.</p>`:'';app.innerHTML=`${updatedNote}${CFG.testPrep?.hide?'':`<section class="prep-banner"><div><b>Test Prep</b> · ${esc(CFG.testPrep?.banner||'Before the paper test: do the Operating warm-up (about 20 minutes).')}</div><button class="primary" data-go="testprep">Open the warm-up →</button></section>`}${journeyHTML()}<section class="hero"><div><div class="eyebrow">Welcome back, ${esc(S.identity.name)} · your learning path</div><h1>See the cash<br>beneath the <em>profit.</em></h1><p>Start with the big question. Follow the evidence. Make the numbers tell the story.</p><button class="primary" id="continue">Continue Learning <span aria-hidden="true">→</span></button><p class="small" style="margin-top:12px">${resume?`Resume your saved step in ${esc(modules.find(m=>m.id===S.active.moduleId)?.title||'your lesson')}`:startedIdx(next.id)>=0?`Pick up where you left off: ${esc(next.title)}`:`Up next: ${esc(next.title)}`}</p></div><div class="cash-visual"><div class="eyebrow">The question behind the statement</div><div class="movement"><div><small>Beginning Cash</small><br><strong>$10,000</strong></div><div class="arrow">→</div><div><small>Ending Cash</small><br><strong>$13,000</strong></div></div><div class="target"><span>What explains the change?</span><strong>+$3,000</strong></div><div class="buckets"><div><b>O</b>Operating</div><div><b>I</b>Investing</div><div><b>F</b>Financing</div></div></div></section><div class="section-head"><h2>Your route to a complete statement</h2><span class="small">${S.lesson.completedModules.length} of ${modules.length} modules explored</span></div>${[...new Set(modules.map(m=>m.group))].map(group=>`<section class="path-group"><h3 class="eyebrow">${esc(group)}</h3><div class="path-grid">${modules.filter(m=>m.group===group).map(m=>{const state=mastery(S.attempts,m.id,CFG.mastery).state,complete=S.lesson.completedModules.includes(m.id),idx=modules.indexOf(m),locked=false,started=startedIdx(m.id)>=0,screens=lesson(m.id,CFG).length,pos=S.lesson.suspended?.[m.id]?.itemIndex??S.lesson.positions?.[m.id]??0;return `<button class="node ${m.id===next.id?'current':''} ${complete?'done':started?'started':'fresh'}" data-module="${m.id}"><span class="num">${complete?'✓':String(idx+1).padStart(2,'0')}</span><span><strong>${esc(m.title==='Unearned Revenue'?conceptName(m.id,CFG):m.title)}</strong><small>${(S.lesson.updated||[]).includes(m.id)&&!complete?'Updated: go through this again':!complete&&started?`In progress · ${Math.min(pos+1,screens)}/${screens} screens`:complete?(state==='Learning'?'Done · revisit anytime':'Done · '+state):m.id===next.id?'Up next':'Not started · '+screens+' screens'}</small></span></button>`;}).join('')}</div></section>`).join('')}<section class="path-group"><h3 class="eyebrow">Build</h3><div class="path-grid"><button class="node ${S.lesson.completedModules.includes('borrowing')?'':'locked'}" data-capstone="beacon-guided" ${S.lesson.completedModules.includes('borrowing')?'':'disabled'}><span class="num">18</span><span><strong>Guided complete statement</strong><small>${S.lesson.completedModules.includes('borrowing')?(S.capstones['beacon-guided']?.completed?'Completed · replay anytime':'Bring the three stories together'):'Unlocks after Financing'}</small></span></button><button class="node" data-go="build"><span class="num">19</span><span><strong>Integrated & independent cases</strong><small>Find your own path through the evidence</small></span></button></div></section>`;document.querySelector('#continue').onclick=()=>nextAction().run();wireJourney();wireCommon();}
function visualHTML(v={}){if(v.learning)return learningVisual(v.learning,CFG);if(v.workedStory)return workedStoryHTML(v.workedStory,CFG);
 if(v.why)return `<div class="why-grid"><div class="card why-card"><div class="eyebrow">The Income Statement says</div><div class="big">$950 profit</div><p class="small">Revenue $1,000 was earned by doing repairs. Electricity $50 was used. Profit = what was <b>earned minus what was used</b>, whether or not cash moved yet.</p></div><div class="card why-card"><div class="eyebrow">The bank account says</div><div class="big">+$650 cash</div><p class="small">Customers handed over $700 so far; $50 went out for electricity. The other $300 is still in customers' pockets.</p></div><div class="card why-card why-wide"><div class="eyebrow">Friday</div><p><b>An $800 loan payment is due.</b> It gets paid out of the bank account, not out of “profit.” Two true numbers, two different questions: <i>How did the business do?</i> is the Income Statement. <i>Where did the cash actually go?</i> is the Statement of Cash Flows. Mix them up and you will believe a profitable company can never run out of money. Plenty have.</p></div></div>`;
 if(v.exhibit)return `<div class="exhibit"><div class="statement card"><div class="statement-head"><strong>Beacon Bike &amp; Repair</strong><span>Income Statement</span><span>Month of June</span></div><table><tbody><tr><td class="l">Repair Revenue</td><td>1,000</td></tr><tr><td class="l">Electricity Expense</td><td>(50)</td></tr><tr class="total"><td class="l">Net Income</td><td>950</td></tr></tbody></table><p class="small">Counts work done and services used, when they happen.</p></div><div class="statement card"><div class="statement-head"><strong>Beacon Bike &amp; Repair</strong><span>Comparative Balance Sheet</span><span>May 31 · June 30</span></div><table><thead><tr><th class="l">Account</th><th>May 31</th><th>June 30</th></tr></thead><tbody><tr><td class="l">Cash</td><td>10,000</td><td>10,650</td></tr><tr class="highlight"><td class="l">Accounts Receivable</td><td>200</td><td>500</td></tr><tr class="total"><td class="l">Total assets</td><td>10,200</td><td>11,150</td></tr><tr><td class="l">Common Stock</td><td>10,200</td><td>10,200</td></tr><tr><td class="l">Retained Earnings</td><td>0</td><td>950</td></tr><tr class="total"><td class="l">Total liabilities &amp; equity</td><td>10,200</td><td>11,150</td></tr></tbody></table><p class="small">Both dates balance. A/R rose $300: customers owe $300 more.</p></div><div class="statement card"><div class="statement-head"><strong>Beacon Bike &amp; Repair</strong><span>Statement of Cash Flows</span><span>Month of June · indirect</span></div><table><tbody><tr><td class="l">Net Income</td><td>950</td></tr><tr class="highlight"><td class="l">Increase in Accounts Receivable</td><td>(300)</td></tr><tr class="total"><td class="l">Net cash from operating activities</td><td>650</td></tr><tr><td class="l">Net change in Cash</td><td>650</td></tr><tr><td class="l">Beginning Cash</td><td>10,000</td></tr><tr class="total"><td class="l">Ending Cash</td><td>10,650</td></tr></tbody></table><p class="small">The shaded source row becomes the shaded adjustment line. $950 − $300 = $650, and $10,000 + $650 = $10,650: it ties.</p></div></div>`;if(v.cash)return `<div class="cash-visual"><div class="movement"><div><small>Beginning Cash</small><br><strong>${money(v.cash[0])}</strong></div><span class="arrow">→</span><div><small>Ending Cash</small><br><strong>${money(v.cash[1])}</strong></div></div><p>What changed between these two dates?</p><div class="buckets"><div>Operating</div><div>Investing</div><div>Financing</div></div></div>`;if(v.bridge)return `<div class="bridge"><div><span>Net Income</span><strong>${money(v.bridge[0])}</strong></div><div><span>Revenue not collected</span><strong>${money(v.bridge[1])}</strong></div><div><span>Operating cash</span><strong>${money(v.bridge[2])}</strong></div></div>`;if(v.matrix)return `<div class="card">${timingMatrix(v.matrix!=='recognition')}</div>`;if(v.offset)return `<div class="bridge"><div><span>Inventory adjustment</span><strong>($100)</strong></div><div><span>A/P adjustment</span><strong>$100</strong></div><div><span>Net cash movement</span><strong>$0</strong></div></div>`;if(v.goal)return `<div class="card goal"><div class="eyebrow">The one question</div><div class="big">Where did the cash come from, and where did it go?</div><table class="t"><tbody><tr><td class="k">Start with profit</td><td>Our first guess at operating cash</td></tr><tr><td class="k">Fix where profit and cash disagree</td><td>That is what every Operating line does</td></tr><tr><td class="k">The phone sale brought in $300</td><td>Real cash, from a long-term asset → its own line in Investing</td></tr><tr><td class="k">Profit has a $100 "gain" baked in</td><td>Not cash; it has to come OUT of Operating</td></tr></tbody></table></div>`;
 if(v.architecture)return `<div class="card arch"><div class="eyebrow">Why did Cash change?</div><table class="t"><tbody><tr><td class="k">Operating</td><td><b>Start with Net Income</b>, then reconcile it to operating cash (timing, noncash items, gains/losses). The lines inside are reconciliation math; only the total is cash.</td></tr><tr><td class="k">Investing</td><td><b>Do not start with Net Income.</b> Actual cash paid or received for long-term assets.</td></tr><tr><td class="k">Financing</td><td><b>Do not start with Net Income.</b> Actual cash moved with lenders and owners.</td></tr><tr class="total"><td class="k">Operating + Investing + Financing</td><td>= Change in Cash</td></tr></tbody></table></div>`;
 if(v.investingFirst)return `<div class="card arch"><div class="eyebrow">Investing's first question</div><table class="t"><tbody><tr><td class="k">Is the cash stated?</td><td>Yes → report it in Investing and stop.</td></tr><tr><td class="k">Not stated?</td><td>Clue 1: amount on the books (cost − accumulated depreciation). Clue 2: gain (paid more) or loss (paid less). Reconstruct the cash.</td></tr><tr><td class="k">Either way</td><td>The gain/loss is removed in Operating. That line is not cash.</td></tr></tbody></table></div>`;
 if(v.five)return `<div class="card five"><div class="eyebrow">The five numbers</div><table class="t"><tbody><tr><td>Cost</td><td class="r">$800</td><td class="tag">not cash</td></tr><tr><td>Accumulated depreciation</td><td class="r">$600</td><td class="tag">not cash</td></tr><tr><td>Book value (cost − acc. dep.)</td><td class="r">$200</td><td class="tag">not cash</td></tr><tr class="hl"><td>Proceeds (what the buyer paid)</td><td class="r">$300</td><td class="tag cash">CASH → Investing</td></tr><tr><td>Gain (proceeds − book value)</td><td class="r">$100</td><td class="tag">not cash · already in Net Income</td></tr></tbody></table></div>`;
 if(v.sale)return `<div class="bridge"><div><span>Net Income already includes the gain</span><strong>+$100</strong></div><div><span>Operating: undo it (subtract)</span><strong>($100)</strong></div><div><span>Investing: the real cash</span><strong>$300</strong></div></div>`;
 if(v.loss)return `<div class="bridge"><div><span>Net Income already includes the loss</span><strong>($50)</strong></div><div><span>Operating: undo it (add back)</span><strong>$50</strong></div><div><span>Investing: the real cash</span><strong>$150</strong></div></div>`;if(v.timeline)return `<div class="timeline">${esc(v.timeline)}</div><p class="small" style="margin-top:20px">${esc(v.assumption||'')}</p>`;return `<div class="card"><div class="eyebrow">Keep the destination in view</div><h2>Why did Cash change?</h2>${mission()}<p class="small">The evidence you find will become lines on a real statement.</p></div>`;}
function renderLesson(){const a=S.active,p=a.problem,m=currentModule(),items=lesson(m.id,CFG);const practice=a.mode==='practice';if(a.shownStep!==a.step||!a.stepShownAt){a.shownStep=a.step;a.stepShownAt=Date.now();a.stepAway=0;a.stepAwaySec=0;a.stepPaste=0;}if(p.type==='observe'){app.innerHTML=moduleHead(m,a.itemIndex,items.length)+mission()+`<section class="lesson-observe"><div><div class="eyebrow">Observe · a small story</div><h2>${esc(p.title)}</h2><div class="story">${p.body.map(t=>`<p>${esc(t)}</p>`).join('')}</div><button class="primary" id="next-observe">Try the reasoning →</button></div><div>${visualHTML(p.visual)}</div></section>`;document.querySelector('#next-observe').onclick=nextProblem;wireCommon();return;}
 const q=p.prompts[a.step],stepHints=hintsFor(p,q),help=a.help[a.step]||{hints:[],revealed:false},draft=a.drafts[a.step]||{},answered=!!a.done;
 const header=practice?`<div class="module-head"><div><div class="eyebrow">${S.practice.focus?'Focus practice':'Mixed practice'} · ${S.practice.done+1} of ${S.practice.size}</div><h1>${esc(conceptName(p.concept,CFG))}</h1><p class="muted">${esc(p.intro)}</p></div><div class="head-side">${S.testPrep?.returnTo?'<button class="link" data-go="testprep">↩ Back to Test Prep</button>':''}<button data-go="practice">Practice choices</button></div></div>`:moduleHead(m,a.itemIndex,items.length);
 const chain=p.scaffoldLevel<=1?'<div class="chain">'+['WHERE','SEE','INTERPRET','CONNECT','ACT','PLACE'].map(t=>`<span class="${t===q.phase?'on':''}">${t}</span>`).join('')+'</div>':'';
 const hintAllowed=!(CFG.assessment?.enabled&&CFG.assessment.disableHints);
 app.innerHTML=header+(a.legacyLessonRevision?'<p class=notice>Your saved question is preserved. Finish it, then the revised lesson begins. Your past work is kept.</p>':'')+mission()+`<div class="workbench">${sourcePanel(p.source,a.sourceTab,p.scaffoldLevel<=2&&a.sourceTab==='bs'?p.concept:null,CFG)}<section class="task-panel"><div class="zone-label">02 / Connect the story · ${a.step+1} of ${p.prompts.length}</div>${chain}<p class="small">${esc(p.intro)}</p><h2 id="question-title" tabindex="-1">${esc(q.text)}</h2><form id="answer-form" aria-labelledby="question-title">${promptInputs(q,draft,answered)}<p id="answer-error" class="form-error" role="alert"></p>${!answered?'<div class="actions"><button class="primary" type="submit">Check my reasoning</button></div>':''}</form>${a.feedback?`<div class="feedback ${a.feedback.correct?'':'wrong'}" role="status"><b>${a.feedback.correct?'✓ That fits.':a.feedback.revealed?'Worked answer':'Let’s trace this back.'}</b><p>${esc(a.feedback.feedback)}</p>${!a.feedback.correct&&!a.feedback.revealed&&backwardPrompt(q,p)?'<button id="step-back" style="margin-top:10px">Work through the earlier step</button>':''}</div>`:''}${help.hints.length?`<div class="hints">${help.hints.map(h=>`<p>${esc(h)}</p>`).join('')}</div>`:''}${help.revealed?`<div class="notice"><b>Worked answer</b><p>${esc(answerText(q.correct))}</p><p>${esc(p.explanation)}</p></div>`:''}<div class="actions">${answered?`<button class="primary" id="next-step">${a.step===p.prompts.length-1?'Continue →':'Next reasoning step →'}</button>`:hintAllowed?`<button id="hint">${help.hints.length?'Another hint':'I need a hint'}</button>${help.hints.length>=Math.min(2,stepHints.length)?'<button class="link" id="reveal">Show worked answer</button>':''}`:''}</div>${answered&&a.step===p.prompts.length-1?`<details class="checklist"><summary>Show the full reasoning</summary>${esc(p.explanation)}</details>`:''}</section><aside class="destination-panel"><div class="zone-label">03 / Build the statement</div>${scfHTML(a.lines,{partial:true,company:p.source.company})}<p class="small" style="margin-top:20px">${a.lines.length?'These are the lines you have placed in this example.':'Your line will appear here after placement.'}</p></aside></div><button class="statement-toggle" id="view-statement">View Statement ↑</button>`;
 wireCommon();document.querySelectorAll('[data-source-tab]').forEach(b=>b.onclick=()=>{a.sourceTab=b.dataset.sourceTab;persist();renderLesson();});
 const form=document.querySelector('#answer-form');form.oninput=()=>{a.drafts[a.step]=readDraft(form);persist();};form.onchange=e=>{form.oninput();if(e.target.name==='section'){renderLesson();document.querySelector('[name=sign]')?.focus();}};
 form.onsubmit=e=>{e.preventDefault();const d=readDraft(form);if(!completeDraft(q,d,parseAmount)){document.querySelector('#answer-error').textContent='Complete each choice and enter a valid amount. A negative amount needs a negative effect. Use 0 for no cash movement.';return;}a.drafts[a.step]=d;const response=responseFor(q,d,parseAmount),result=evaluate(q,response,p);record(S,p,q,response,result,{opportunityId:a.opportunityId,moduleId:a.moduleId||null,mode:a.mode,guided:!!a.legacyLessonRevision,hintsUsed:help.hints,revealed:!!(help.revealed||a.solutionSeen),elapsedMs:Date.now()-a.startedAt,stepSec:Math.round((Date.now()-(a.stepShownAt||a.startedAt))/1000),away:a.stepAway||0,awaySec:Math.round(a.stepAwaySec||0),pasted:a.stepPaste||0,focusedPractice:a.mode==='practice'&&!!S.practice?.focus});a.feedback=result;
 if(result.correct){a.done=true;placeAnswer(a,q);}else{scheduleRetry(S,p,q.skill,result.misconceptionCode,CFG.practice);a.failed=true;}
 persist();renderLesson();document.querySelector('.feedback')?.scrollIntoView({block:'nearest'});document.querySelector('#next-step')?.focus({preventScroll:true});};
 document.querySelector('#next-step')?.addEventListener('click',()=>{if(a.step+1===p.prompts.length){nextProblem();return;}a.step++;if(p.prompts[a.step].sourceTab)a.sourceTab=p.prompts[a.step].sourceTab;a.done=false;a.feedback=null;a.startedAt=Date.now();persist();renderLesson();document.querySelector('#question-title')?.focus({preventScroll:true});document.querySelector('#question-title')?.scrollIntoView({block:'nearest'});});
 document.querySelector('#hint')?.addEventListener('click',()=>{const h=a.help[a.step]||(a.help[a.step]={hints:[],revealed:false});if(h.hints.length<stepHints.length)h.hints.push(stepHints[h.hints.length]);persist();renderLesson();});
 document.querySelector('#reveal')?.addEventListener('click',()=>{const h=a.help[a.step]||(a.help[a.step]={hints:[],revealed:false});if(h.revealed)return;h.revealed=true;a.solutionSeen=true;a.feedback={correct:false,feedback:'The worked answer is shown below. Enter it yourself to continue; this counts as learning support, not an independent success.',revealed:true};record(S,p,q,'Revealed',{correct:false,misconceptionCode:null},{opportunityId:a.opportunityId,moduleId:a.moduleId||null,mode:a.mode,guided:!!a.legacyLessonRevision,hintsUsed:h.hints,revealed:true});scheduleRetry(S,p,q.skill,null,CFG.practice);persist();renderLesson();document.querySelector('#answer-form input:not([disabled]),#answer-form select:not([disabled])')?.focus();});
 document.querySelector('#view-statement').onclick=()=>modal('Your statement',scfHTML(a.lines,{partial:true,company:p.source.company}));
 document.querySelector('#step-back')?.addEventListener('click',()=>renderRemediation(backwardPrompt(q,p),p,a));
}
function placeAnswer(a,q){if(q.type==='place'&&!a.lines.some(l=>l.id===String(a.step)))a.lines.push({id:String(a.step),label:q.label,section:q.correct.section,amount:q.correct.amount});}
function answerText(v){if(typeof v==='object')return Array.isArray(v)?v.join(', '):`${v.section?sectionName(v.section):v.direction} · ${money(v.amount)}`;return typeof v==='number'?money(v):v;}
function renderRemediation(q,p,a){modal('One step back',`<p>${esc(q.text)}</p><form id="remediate">${promptInputs(q)}<div id="remediate-feedback" role="status"></div><button class="primary" type="submit">Check this step</button></form>`);document.querySelector('#remediate').onsubmit=e=>{e.preventDefault();const draft=readDraft(e.currentTarget);if(!completeDraft(q,draft,parseAmount))return;const response=responseFor(q,draft,parseAmount),r=evaluate(q,response,p);record(S,p,q,response,r,{mode:'remediation',opportunityId:a.opportunityId,hintsUsed:['Backward reasoning support'],revealed:false});const h=a.help[a.step]||(a.help[a.step]={hints:[],revealed:false});if(!h.hints.includes('Backward reasoning support'))h.hints.push('Backward reasoning support');persist();document.querySelector('#remediate-feedback').innerHTML=`<p class="notice">${esc(r.correct?'That’s the bridge. Return to the adjustment and try again.':r.feedback)}</p>${r.correct?'<button type="button" id="back-to-task">Return to my answer</button>':''}`;document.querySelector('#back-to-task')?.addEventListener('click',()=>{close();renderLesson();});};}
function renderModuleDone(){const mid=S.completedNow,m=modules.find(x=>x.id===mid),idx=modules.indexOf(m),next=(modules.some(x=>!S.lesson.completedModules.includes(x.id))?resumeTarget(mid):null),prompt=milestone(mid);app.innerHTML=`<section class="result card"><div class="check">✓</div><div class="eyebrow">Concept explored</div><h1>${esc(m?.title||'Learning step')}.</h1><p>${S.lesson.revisit.includes(mid)?'You’re still building this skill. We’ll bring it back in practice.':'You have connected the story to the statement.'}</p>${prompt?`<form id="explanation-form" style="text-align:left"><label class="field">${esc(prompt)}<textarea name="explanation" maxlength="1000" ${CFG.explanations?.required?'required':''} placeholder="One sentence in your own words">${esc(S.explanations.find(e=>e.moduleId===mid)?.text||'')}</textarea><small>Mr. Sorensen reads these. No automated writing score.</small></label><button type="submit">Save my explanation</button><span id="explanation-saved" role="status"></span></form>`:''}<p class="small muted">${next?`Next: <b>${esc(next.title)}</b> (module ${modules.indexOf(next)+1} of ${modules.length}; ${modules.length-S.lesson.completedModules.length} left in Learn).`:'That was the last learning module. Step 2 is Practice until your concepts show Secure; step 3 is Build a Statement.'}</p><div class="actions"><button class="primary" id="continue-module">${next?'Continue to '+esc(next.title):(nextAction().label+' →')}</button>${S.testPrep?.returnTo?'<button data-go="testprep">↩ Back to Test Prep</button>':''}<button data-go="home">View learning map</button></div></section>`;document.querySelector('#continue-module').onclick=()=>{if(CFG.explanations?.required&&prompt&&!S.explanations.some(e=>e.moduleId===mid&&e.text.trim().length>=10)){toast('Save a short explanation before continuing.');return;}next?startModule(next.id):nextAction().run();};document.querySelector('#explanation-form')?.addEventListener('input',e=>{const text=e.currentTarget.elements.explanation.value;const old=S.explanations.find(x=>x.moduleId===mid);if(old)old.text=text;else S.explanations.push({moduleId:mid,text,timestamp:Date.now()});persist();});document.querySelector('#explanation-form')?.addEventListener('submit',e=>{e.preventDefault();persist();document.querySelector('#explanation-saved').textContent=' Saved ✓';});wireCommon();}
function renderPractice(){const concepts=S.lesson.introducedConcepts.filter(c=>PRACTICE_CONCEPTS.includes(c));app.innerHTML=`${journeyHTML()}<div class="eyebrow">Practice · step 2 of 3 · keep the reasoning alive</div><h1 style="font-size:2.8rem">Choose your next connection.</h1><p class="muted">Practice is available for concepts you have encountered. Mistakes return later with new numbers.</p><div class="practice-grid"><section class="card"><h2>Mixed practice</h2><p class="muted">A short set weighted toward skills that need another look.</p><button class="primary" data-start-mixed ${concepts.length?'':'disabled'}>Start mixed set →</button></section><section class="card"><h2>My weakest skill</h2><p class="muted">Work on the precise link that needs support.</p><button id="weakest" ${concepts.length?'':'disabled'}>Target my next step</button></section><section class="card"><h2>Build Operating</h2><p class="muted">Combine Net Income, noncash, gains, and timing.</p><button data-capstone="mini-operating">Open mini statement</button></section></div><div class="section-head"><h2>Focus on one concept</h2></div><div class="path-grid">${concepts.map(c=>`<button class="node" data-focus="${c}"><span><strong>${esc(conceptName(c,CFG))}</strong><small>${mastery(S.attempts,c,CFG.mastery).state} · varied skills, ${CFG.practice?.focusSize||6} questions</small></span></button>`).join('')||'<p class="notice">Start with The Cash Mystery in Learn. Concepts appear here as they are introduced.</p>'}</div>`;document.querySelector('#weakest').onclick=()=>{const c=[...concepts].sort((a,b)=>(mastery(S.attempts,a).score??.3)-(mastery(S.attempts,b).score??.3))[0];startPractice(c,true);};wireCommon();}
function renderBuild(){const {ready,secureOps,acc,gateOn,guidedOK,integratedOK}=capstoneGates();const gateNote=(id)=>id==='beacon-guided'&&!guidedOK?`<small>Recommended once 3 Operating concepts are Secure and recent accuracy is 60%+ (now: ${secureOps} secure, ${acc==null?'—':Math.round(acc*100)+'%'}). Open anytime.</small>`:id==='beacon-integrated'&&!integratedOK?`<small>Recommended after the guided statement, with 5 Operating concepts Secure and 70%+ recent accuracy (now: ${secureOps}, ${acc==null?'—':Math.round(acc*100)+'%'}). Open anytime.</small>`:'';app.innerHTML=`${journeyHTML()}<div class="eyebrow">Build · step 3 of 3 · explain the complete cash change</div><h1 style="font-size:2.8rem">Bring all three stories together.</h1><p class="muted">Use the documents, place the lines, and make beginning Cash reconcile to ending Cash.</p><div class="practice-grid">${[['beacon-guided','01 · Guided','A source-by-source scan, with reasoning support.'],['beacon-integrated','02 · Integrated','All timing accounts. You choose the lines and diagnose the tie-out.'],['cedar-independent','03 · Independent','Reversed timing, an equipment gain, and a noncash boundary.']].map(([id,title,body])=>`<section class="card"><h2>${title}</h2><p>${body}</p><span class="status">${S.capstones[id]?.completed?'Completed · replay available':S.capstones[id]?'In progress':'Not started'}</span><button class="primary" data-capstone="${id}" >${S.capstones[id]?'Resume / review':'Open statement'} →</button>${id==='cedar-independent'&&!ready?'<small>Recommended after the integrated statement.</small>':!S.lesson.completedModules.includes('borrowing')&&!S.capstones[id]?'<small>Recommended after the Financing module; open anytime.</small>':gateNote(id)}</section>`).join('')}</div><details class="card checklist" style="margin-top:24px" open><summary><b>The construction route</b></summary>${checklist()}</details>`;wireCommon();}
function renderProgress(){app.innerHTML=`<div class="eyebrow">Your progress · recent evidence matters</div><h1 style="font-size:2.8rem">See what is becoming clear.</h1><p class="muted">Guided success builds understanding. Secure and Mastered require independent evidence, varied skills, and both timing directions.</p><div class="path-grid">${S.lesson.introducedConcepts.filter(c=>PRACTICE_CONCEPTS.includes(c)).map(c=>{const m=mastery(S.attempts,c,CFG.mastery);return `<section class="card"><h2>${esc(conceptName(c,CFG))}</h2><span class="status ${m.state.toLowerCase()}">${m.state}</span><div class="skill-list">${['locate','compute_change','interpret','recognition_cash_connect','place_line'].map(k=>{const st=skillStats(S.attempts,c,k);return `<span>${st.state==='Secure'?'✓':st.count?'△':'○'} ${SKILL_NAMES[k]}</span>`;}).join('')}</div><button data-focus="${c}">Practice this concept</button></section>`;}).join('')||'<p>Evidence will appear as you learn.</p>'}</div>`;wireCommon();}
function wireCommon(){wireJourney();document.querySelector('#lesson-back')?.addEventListener('click',lessonBack);document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>route(b.dataset.go));document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>startModule(b.dataset.module));document.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>startPractice(b.dataset.focus));document.querySelectorAll('[data-start-mixed]').forEach(b=>b.onclick=()=>startPractice());document.querySelectorAll('[data-capstone]').forEach(b=>b.onclick=()=>{startCapstone(S,b.dataset.capstone);persist();render();});}
function wireBuilder(){wireCommon();handleBuilder(app,S,CFG,{persist,render,toast,modal,record});document.querySelector('#view-statement')?.addEventListener('click',()=>modal('Your statement',scfHTML(currentCapLines(S),{partial:false,beginCash:S.capstones[S.currentCapstone]?.beginCash})));}
function settings(){modal('Your settings & backup',`<div class="stack"><label class="field">Theme<select id="theme"><option value="light" ${S.settings.theme==='light'?'selected':''}>Light</option><option value="dark" ${S.settings.theme==='dark'?'selected':''}>Dark</option></select></label><p class="small">This browser stores the current learner’s work. Export before changing devices or clearing browser data.</p><div class="row"><button id="export">Export progress</button><label class="field" style="margin:0">Import progress<input id="import" type="file" accept=".json,application/json"></label></div>${storageError?`<p class="notice warn">${esc(storageError)}</p><button id="raw-export">Export original saved data</button>`:''}<details><summary>Start over on this device</summary><p class="small">Export first. Reset removes this browser’s saved learning progress; cloud records are not deleted.</p><label class="field">Type RESET<input id="reset-word" autocomplete="off"></label><button id="reset">Reset local progress</button></details></div>`);document.querySelector('#theme').onchange=e=>{S.settings.theme=e.target.value;persist();render();};document.querySelector('#export').onclick=()=>download('cash-flow-lab-progress.json',JSON.stringify(S,null,2));document.querySelector('#raw-export')?.addEventListener('click',()=>download('cash-flow-lab-original.json',localStorage.getItem(STORAGE_KEY)||''));document.querySelector('#import').onchange=async e=>{try{const file=e.target.files[0];if(!file||file.size>20000000)throw new Error('Choose a progress JSON file under 20 MB.');const imported=migrate(JSON.parse(await file.text()));if(!imported.identity?.name)throw new Error('This file has no learner identity.');if(S.identity&&S.identity.name!==imported.identity.name)throw new Error('This file belongs to a different learner. Export and reset before importing it.');imported.uid=S.uid;imported.cloud={sent:[],status:'local'};S=imported;ensurePrep();storageError=null;persist();close();render();toast('Progress imported.');}catch(err){toast(err.message);}};document.querySelector('#reset').onclick=()=>{if(document.querySelector('#reset-word').value!=='RESET'){toast('Type RESET to confirm.');return;}S=fresh();ensurePrep();storageError=null;persist(false);close();render();};}
document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>route(b.dataset.nav));document.querySelector('#reference').onclick=()=>{if(CFG.assessment?.enabled&&CFG.assessment.disableReference){toast('Reference is disabled for this assessment.');return;}modal('Your field guide',referenceHTML(S));};document.querySelector('#close-drawer').onclick=close;drawer.addEventListener('click',e=>{if(e.target===drawer){const r=drawer.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});document.querySelector('#profile').onclick=()=>route('progress');document.querySelector('#settings').onclick=settings;
window.addEventListener('hashchange',()=>{if(location.hash==='#home')route('home');});window.addEventListener('online',()=>cloud.schedule());
document.addEventListener('visibilitychange',()=>{const a=S.active;if(!a)return;if(document.hidden){a.hiddenAt=Date.now();}else if(a.hiddenAt){a.stepAway=(a.stepAway||0)+1;a.stepAwaySec=(a.stepAwaySec||0)+(Date.now()-a.hiddenAt)/1000;a.hiddenAt=null;persist();}});
app.addEventListener('paste',e=>{const a=S.active;if(a&&e.target.closest('#answer-form')){a.stepPaste=(a.stepPaste||0)+1;persist();}});
if(CFG.assessment?.enabled){if(CFG.assessment.noCopy)['copy','cut','contextmenu'].forEach(ev=>app.addEventListener(ev,e=>{if(!e.target.closest('textarea'))e.preventDefault();}));if(CFG.assessment.swapOnLeave)document.addEventListener('visibilitychange',()=>{if(document.hidden&&S.active?.mode==='practice')S.pendingSwap=true;else if(S.pendingSwap){S.pendingSwap=false;S.practice.seed+=104729;const p=selectPractice(S,CFG);S.active=newActive(p,{mode:'practice'});persist();render();toast('A fresh variant replaced the unsubmitted assessment question.');}});}
if(storageError){document.querySelector('#save-status').textContent=storageError;document.querySelector('#save-status').classList.add('error');}
render();cloud.init();try{const f=document.querySelector('.footer');if(f&&!f.querySelector('.ver')){const v=document.createElement('span');v.className='ver small muted';v.textContent='v'+VERSION;f.insertBefore(v,f.querySelector('span'));}}catch(e){}


if(PREVIEW_MODULE&&modules.some(x=>x.id===PREVIEW_MODULE)){if(!S.identity){S.identity={first:'Preview',last:'P',block:(CFG.blocks?.[0]?.id)||'1'};persist();}try{startModule(PREVIEW_MODULE);persist();}catch(e){console.warn('preview open failed',e);}}
render();